     ================================ */
  
  :focus-visible {
    outline: 2px solid #38bdf8;
    outline-offset: 2px;
  }

  :focus:not(:focus-visible) {
    outline: none;
  }

  /* ================================
     SELECTION
     ================================ */
  
  ::selection {
    background: rgba(56, 189, 248, 0.3);
    color: #f8fafc;
  }

  /* ================================
